"""People Express course note; quantitative results are built from archived CSV."""
import csv
from html import escape


def render_note(root):
    with (root / 'assets/people-express/local-fixed.csv').open(encoding='utf-8-sig') as f:
        rows = list(csv.DictReader(f))
    first, last = rows[0], rows[-1]
    def table(headers, records, caption):
        return '<div class="pe-table" tabindex="0" role="region" aria-label="'+escape(caption)+'"><table><caption>'+escape(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+escape(str(v))+('</th>' if i==0 else '</td>') for i,v in enumerate(record))+'</tr>' for record in records)+'</tbody></table></div>'
    metrics=[('機隊','Planes','架'),('員工','Staff','人'),('每週工時','WorkHours','小時'),('載客率','LoadFactor_pct','%'),('聲譽','Reputation',''),('季度營收','Revenue_M','M'),('季度淨利','NetIncome_M','M'),('現金','Cash_M','M'),('長期負債','Debt_M','M')]
    summary=table(['指標','1981 Q1 初始','1991 Q1 最終'],[(label,first[key]+unit,last[key]+unit) for label,key,unit in metrics],'初始與期末成果（M＝百萬美元）')
    points=' '.join(f'{55+i*620/(len(rows)-1):.1f},{235-float(r["NetIncome_M"])*2.3:.1f}' for i,r in enumerate(rows))
    grid=''.join(f'<line x1="55" y1="{235-v*2.3}" x2="675" y2="{235-v*2.3}" class="grid"/><text x="43" y="{239-v*2.3}" text-anchor="end">{v}</text>' for v in [0,20,40,60,80])
    labels=''.join(f'<text x="{55+i*620/40}" y="265" text-anchor="middle">{1981+i//4}</text>' for i in [0,8,16,24,32,40])
    chart=f'<figure class="chart-panel"><h3>擴張之後，獲利曾經回落</h3><svg class="chart" viewBox="0 0 720 285" role="img" aria-label="1981至1991季度淨利，1987年回落，暫停擴張後恢復成長"><title>季度淨利（百萬美元）</title>{grid}{labels}<polyline points="{points}" class="line" stroke="#172d46"/></svg><figcaption class="source-note">橫軸：模擬年份；縱軸：季度淨利（百萬美元）。完整季度資料可於下方展開或下載。</figcaption></figure>'
    full=table(['季度','飛機','員工','載客率 %','票價','營收 M','淨利 M'],[(r['Period'],r['Planes'],r['Staff'],r['LoadFactor_pct'],r['Fare'],r['Revenue_M'],r['NetIncome_M']) for r in rows],'修正版逐季紀錄，共41筆（含初始狀態）')
    presets=table(['策略','結果','期末機隊','累計淨利'],[('Burr','第9季（1983 Q2）破產','38架','$19.24M（破產時）'),('穩健','完成40季，聲譽跌到0.26','48架','$470.22M'),('保守','完成40季，從未虧損','10架','$1,052.77M'),('我的自訂策略','完成40季，從未虧損','53架','$1,989.06M')],'本機修正版的預設策略對照')
    return '''
<nav class="breadcrumbs" aria-label="麵包屑"><a href="../notes.html">每週筆記</a><span aria-hidden="true">/</span><span>人民航空</span></nav>
<header class="article-head"><p class="article-meta">2026-10-16 · 課堂筆記</p><h1>人民航空</h1><p class="article-subtitle">成長、擴張與獲利</p><div class="tags"><span>系統思考</span><span>人力培訓</span><span>經營模擬</span></div><p class="article-intro">我原本想靠增加飛機賺更多錢，卻發現規模變大，淨利也可能下降。這次練習讓我學會把需求、人力與交付延遲一起放進決策。</p></header>
<div class="article-layout"><nav class="article-toc" aria-label="本篇目錄"><p class="section-label">IN THIS NOTE</p><a href="#class">課堂筆記</a><a href="#questions">作業問題</a><a href="#strategy">我的策略</a><a href="#results">經營成果</a><a href="#reflection">我的反思</a><a href="#sources">版本與報表</a></nav><article class="article-content">
<section id="class" class="article-section"><h2>課堂筆記：成長為什麼有上限？</h2>
<dl class="concepts"><div><dt>01　解除管制與市場進入</dt><dd>老師說明 Deregulation 就是民營化，從公營轉為民營，民間業者可以進入原本受限的市場。課堂舉了第四台與報禁、報紙、銀行和電信服務的例子，討論開放之後帶來的工作與市場機會。老師也提到，現在的無人機也是一個很有潛力的市場。開放讓機會變多，但不是每家業者都能因此獲利。</dd></div><div><dt>02　低價背後的商業模式</dt><dd>老師用白板拆解低價航空的商業模式：不供應餐點、不托運行李，讓飛機更輕、更省油，費用降低後才能壓低票價，低價本身就是吸引力。另外我也從來沒想過的是機場的停靠費都可以省，雖然可以東減西減些服務，但也得保有相應的成本結構撐住，不只是把售價壓低。由此可以看出原來很多服務費是可以省的，但不是一味追逐減少成本。</dd></div><div><dt>03　口碑帶動成長，服務能力限制成長</dt><dd>服務品質變好，會帶來口碑和新客；銷售和現金增加後，可以支持航線與機隊擴張。不過旅客變多，服務的工作量也跟著變多。如果培訓和人力跟不上，品質就會下降，反過來傷害口碑。我把它記成兩股同時存在的力量。</dd></div><div><dt>04　投資有時間延遲</dt><dd>飛機和航線很容易被當成成長的重點，但人員招募和訓練耗時費力。老師從「成長上限」講到「成長與投資不足」：成長曲線到後來變平，是因為人力（HR）沒有跟上。本來應該把重點放在人才，卻反而一直擴充航線和飛機，簡直是捨本逐末。所有經營策略如果都是等到瓶頸才開始招攬新人才，這樣亡羊補牢的急救可能已經來不及。</dd></div></dl>
<div class="pe-loop"><p><strong>促進成長：</strong>服務品質 → 口碑 → 客源與收入 → 投資擴張</p><p><strong>限制成長：</strong>客源增加 → 工作負荷增加 → 若服務能力跟不上，品質與口碑下降</p></div>
<details class="swot-supplement"><summary>查看 10/16 課堂白板照片（3 張）</summary><figure class="class-photo"><img src="../assets/people-express/whiteboard-1016-1-business-model.jpg" alt="10/16 課堂白板：低價航空的商業模式與解除管制" loading="lazy"><figcaption>1. 10/16 白板：低價航空的商業模式與解除管制</figcaption></figure><figure class="class-photo"><img src="../assets/people-express/whiteboard-1016-2-causal-loop.jpg" alt="10/16 課堂白板：服務品質、口碑與擴張的因果循環" loading="lazy"><figcaption>2. 10/16 白板：服務品質、口碑與擴張的因果循環</figcaption></figure><figure class="class-photo"><img src="../assets/people-express/whiteboard-1016-3-growth-limits.jpg" alt="10/16 課堂白板：成長上限與成長投資不足" loading="lazy"><figcaption>3. 10/16 白板：成長上限與成長投資不足</figcaption></figure></details></section>
<section id="questions" class="article-section"><h2>作業問題與我的回答</h2>
<div class="lesson-block"><h3>1. Burr 策略會多快破產？賠多少？</h3><p>在老師的原版模擬器套用 Burr 預設（每季訂4架、招募40人），第8季、也就是1983 Q1，現金降到 −$23.52M，跌破 −$20M 的破產門檻，模擬器宣告破產。破產當季淨損 $49.73M，是最差的單季結果；三個虧損季度的淨損合計 $97.63M。</p><p>破產時累計淨利仍為正 $28.10M。每訂一架飛機要先付 $2M 現金，8季共訂32架、付出 $64M，現金在獲利累積之前就被購機用光。這讓我看見現金不足和累計虧損是不同的情況。</p><p>不過原版有兩個輸入錯誤：票價滑桿的數值沒有除以1000，一律被限制在上限 $0.250；Burr 預設的行銷10%會被滑桿歸零，再被程式改回預設8%。所以這份紀錄是 Burr 的購機與招募節奏，搭配錯誤的票價與行銷。用本機修正版重跑 Burr 預設（票價 $0.085、行銷10%），第9季（1983 Q2）破產，現金降到 −$40.38M，最差單季淨損 $44.92M，虧損季度合計 $76.13M。</p></div>
<div class="lesson-block"><h3>2. 保守策略能持續攢到錢嗎？</h3><p>可以。用本機修正版套用保守預設（票價 $0.120、不購機、每季招募10人、行銷5%、服務深度0.20）跑完40季，機隊一直維持10架，每季穩定獲利約 $26.24M，沒有任何虧損季度，累計淨利 $1,052.77M。代價是規模不再成長，每季獲利也停在同一水準。</p>'''+presets+'''<p>我的自訂策略在後期停止購機、減少招募後，從1987 Q4至1989 Q2持續獲利，現金由 $972.10M增至 $1,377.89M。和保守預設相比，先擴張、再放慢的做法累計淨利約多出0.9倍，但也經歷了1987年的獲利回落。</p><p class="source-note">預設策略的結果是以本機修正版依各預設參數連續推進的補充測試，未另外匯出報表。</p></div>
<div class="lesson-block"><h3>3. 我的策略組合是什麼？</h3><p>我先用 $0.090 的低票價和約 9% 的行銷打開市場，每季買 1 到 2 架飛機，同時提早把每季招募從 35 人加到 110 人，服務深度大多維持 0.30 的輕服務。1987 年發現需求跟不上機隊後，我停止買飛機、把招募降到 50 人，再依獲利和載客率微調票價。40 季的轉折整理在下方「我的策略」。</p></div>
<div class="lesson-block"><h3>4. 報表保存與上傳</h3><p>我已匯出原版與本機修正版兩份CSV。本次主要成果採用本機修正版。Google試算表尚未確認登錄：回傳只會送出請求，瀏覽器無法確認是否寫入，需要在模擬器以左上角綠色按鍵上傳後，再向老師核對。</p></div></section>
<section id="strategy" class="article-section"><h2>我的策略：先成長，再修正速度</h2>
<ul class="observations"><li><strong>票價：</strong>以 $0.090起步，成長期先後提高到 $0.095、$0.100；需求轉弱後回到 $0.095。後期再次測試 $0.100未提高當季淨利，最終維持 $0.095。</li><li><strong>客機量：</strong>從每季訂1架開始，之後提高到2架，曾追加到3架；需求追不上時停止新訂單，讓機隊停在51架。最後恢復少量訂購，期末已交付53架。</li><li><strong>新手招募：</strong>從每季35人逐步提高到60、70、100與110人；停止擴張後降到約50人，接近補足離職。招募人數不等於員工淨增加人數。</li><li><strong>服務深度：</strong>依操作紀錄主要維持0.30的輕服務，沒有把提高服務深度當作主要實驗變數。</li><li><strong>行銷：</strong>初期從8%提高到約9%，以增加品牌認識與客源；後續主要調整購機、招募與票價。</li></ul><p class="source-note">票價與機隊成果可由CSV核對；招募、行銷與服務深度依操作對話整理。匯出檔未包含完整決策設定，不能視為逐季精確的操作清單。</p>
<div class="lesson-block"><h3>1981–1986：擴張與補足人力</h3><p>初期載客率很快到92%。新機交付帶來更多運能，我也逐漸意識到離職與新人培訓會影響服務能力，因此提高招募。1985 Q2起工時逐步下降，正好接在1985 Q1把每季招募提高到100人之後，代表補人的速度開始跟上擴張。</p></div>
<div class="lesson-block"><h3>1987：飛機變多，淨利反而下降</h3><p>從Q1到Q4，機隊由44架增加到51架，載客率由92%降至81.1%，季度淨利由 $74.40M降至 $53.36M。模型中的競爭者逐步反擊、航網吸引力達上限，加上運能擴張，讓我發現買機不保證獲利增加。即使停止訂購，在途飛機仍會繼續到貨。</p></div>
<div class="lesson-block"><h3>1988–1989：穩住規模，重新累積獲利</h3><p>機隊維持51架，員工人數大致穩定。隨市場需求與聲譽改善，載客率逐漸回到92%。1989 Q3把票價從 $0.095調到 $0.100後，淨利從前季 $76.74M降至 $76.16M，所以我調回原價。這是不同季度的比較，不能將全部差異歸因於票價。</p></div>
<div class="lesson-block"><h3>1990–1991 Q1：恢復少量購機</h3><p>末期機隊從51架增加到53架，載客率維持92%，最終季度淨利達 $80.12M。負債在最後四季每季增加 $5M，依照每架飛機的融資設定，我推測這段期間每季都訂購1架，期末可能還有2架在途。模擬接近結束，這段擴張的長期效果還沒有足夠時間觀察。</p></div></section>
<section id="results" class="article-section"><h2>經營成果</h2><p>模擬從1981 Q1起始，到1991 Q1結束，共40次推進、41筆狀態。修正版所有季度淨利皆為正，最終累計淨利為 <strong>$1,989.06M</strong>（約19.89億美元，含初始季度）。現金與累計淨利不同，購機現金支出與融資會影響兩者。</p>'''+summary+chart+'''<p>這是一次成功維持獲利的經營，但還不是最佳策略的證明。1987 Q1每架飛機季度淨利約 $1.69M，期末約 $1.51M；公司規模擴大了，單位效率卻未回到當時水準。市場與競爭環境也隨時間改變，不能只用一個比值判定成敗。</p><details class="swot-supplement"><summary>查看完整41筆季度成果</summary>'''+full+'''</details></section>
<section id="reflection" class="article-section"><h2>我的反思</h2><div class="reflection"><p>我一開始的目標很直接，就是想把公司做大、賺更多錢。看到載客率一直維持92%、淨利逐季增加，就覺得可以繼續買飛機。直到機隊變大、載客率卻開始下降，我才真正理解：增加供給不代表市場會自動產生同樣多的需求。</p><p>人力也是一樣。我原本只看每季招募的人數，後來才把離職人數算進去，也發現新人需要培訓，不能把總人數直接當成成熟的服務能力。這呼應課堂的成長限制與投資不足：如果只投資看得見的飛機，忽略需要時間累積的人才與口碑，成長就會遇到瓶頸。</p><p>最讓我意外的是，暫停買飛機後，淨利反而逐步恢復。休養生息不是停止經營，而是讓原本的設備和人力發揮效益。未來若再試一次，我想更早注意每架飛機的獲利，並分別測試行銷支出與更細的票價變化，而不是只追求機隊數量。</p></div></section>
<section id="sources" class="article-section"><h2>版本、資料與下載</h2><p>主要分析使用本機修正版：修正票價、行銷比例的輸入換算，以及相關預設值／零值處理；保留經營模型的需求與成本規則。92%的載客率上限、兩季交機與一季培訓都是本次模擬的設定，不能直接當作真實航空公司的標準。</p>
<ul class="sources"><li><a href="../assets/people-express/local-fixed.csv" download>下載完整修正版報表（CSV，41筆）</a></li><li><a href="../assets/people-express/original.csv" download>下載原版 Burr 預設紀錄（CSV，9筆；票價與行銷輸入錯誤）</a></li><li><a href="https://irradiated-banjo-bc0.notion.site/Simulator-3fac98d8903b80cfb9ece2d2c634e21d" target="_blank" rel="noopener noreferrer">老師的Simulator作業說明 ↗</a></li><li><a href="https://changchaoching.github.io/Simulate-People-Express-GAS/" target="_blank" rel="noopener noreferrer">人民航空模擬器原站 ↗</a></li><li>10/16課堂白板照片 IMG_0055、IMG_0060、IMG_0061；10/17及10/21操作截圖、決策對話與匯出報表。</li></ul><p class="source-note">原版與本機修正版的輸入結果不同，兩份紀錄不是相同條件下的對照實驗；比較預設策略時只使用本機修正版的結果。</p></section><a class="back-link" href="../notes.html">← 返回每週筆記</a></article></div>'''
